export const Sculpture = () => {
  return (
    <motion.div 
      className="relative flex flex-col items-center justify-end cursor-pointer" 
      style={{ width: 80, height: 110, transformOrigin: 'bottom center' }}
      initial="initial"
      whileHover="hover"
    >
      <svg viewBox="0 0 80 110" className="w-full h-full overflow-visible">
        <defs>
          <linearGradient id="obelisk-left" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#334155" />
            <stop offset="100%" stopColor="#0f172a" />
          </linearGradient>
          <linearGradient id="obelisk-right" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#64748b" />
            <stop offset="100%" stopColor="#334155" />
          </linearGradient>
          <radialGradient id="gold-glow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#fcd34d" stopOpacity="1" />
            <stop offset="50%" stopColor="#d97706" stopOpacity="0.8" />
            <stop offset="100%" stopColor="#78350f" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Base Shadow */}
        <ellipse cx="40" cy="102" rx="25" ry="6" fill="#164e63" opacity="0.4" />

        {/* Base Plate */}
        <ellipse cx="40" cy="98" rx="22" ry="5" fill="#b45309" />
        <ellipse cx="40" cy="95" rx="22" ry="5" fill="#fcd34d" />

        {/* Central Energy Beam (Visible when fractured) */}
        <motion.line 
          x1="40" y1="90" x2="40" y2="20" 
          stroke="url(#gold-glow)" strokeWidth="6" strokeLinecap="round"
          variants={{
            initial: { opacity: 0 },
            hover: { opacity: 1, transition: { duration: 0.5 } }
          }}
        />

        {/* BOTTOM SEGMENT */}
        <motion.g variants={{ initial: { y: 0 }, hover: { y: -2, transition: { duration: 1.5, repeat: Infinity, repeatType: "reverse", ease: "easeInOut" } } }}>
          {/* Top Face (Glowing Gold) */}
          <polygon points="29,73 40,78 55,70 44,65" fill="#f59e0b" />
          {/* Left Face */}
          <polygon points="25,93 40,100 40,78 29,73" fill="url(#obelisk-left)" />
          {/* Right Face */}
          <polygon points="40,100 60,90 55,70 40,78" fill="url(#obelisk-right)" />
        </motion.g>

        {/* MIDDLE SEGMENT */}
        <motion.g variants={{ initial: { y: 0 }, hover: { y: -15, transition: { duration: 1.5, repeat: Infinity, repeatType: "reverse", ease: "easeInOut" } } }}>
          {/* Top Face (Glowing Gold) */}
          <polygon points="34,46 40,50 49,44 43,40" fill="#f59e0b" />
          {/* Left Face */}
          <polygon points="29.5,71 40,76 40,50 34,46" fill="url(#obelisk-left)" />
          {/* Right Face */}
          <polygon points="40,76 54.5,68 49,44 40,50" fill="url(#obelisk-right)" />
        </motion.g>

        {/* TOP SEGMENT */}
        <motion.g variants={{ initial: { y: 0 }, hover: { y: -30, transition: { duration: 1.5, repeat: Infinity, repeatType: "reverse", ease: "easeInOut", delay: 0.2 } } }}>
          {/* Left Face */}
          <polygon points="34.5,44 40,48 40,15" fill="url(#obelisk-left)" />
          {/* Right Face */}
          <polygon points="40,48 48.5,42 40,15" fill="url(#obelisk-right)" />
          
          {/* Glowing tip flare */}
          <motion.circle 
            cx="40" cy="15" r="4" fill="#ffffff"
            variants={{
              initial: { opacity: 0, scale: 0 },
              hover: { opacity: 0.8, scale: 1.5, transition: { duration: 0.5, delay: 0.5 } }
            }}
          />
        </motion.g>
      </svg>
    </motion.div>
  );
};
